ROOT = dict(id='C1447', meaning='在下面；下一级；低于；接近',
 core='先找一个参照物：在它下方、属于它的下一层，或者还没达到它的标准。',
 image='海面下是 submarine，集合里面的小集合是 subset，标准线下是 substandard；三种“下面”并不一样。',
 intro='拉丁语 sub 既能表示在下面，也能表示从下向上、靠近。英语把 sub- 变成很活跃的构词前缀，可以接拉丁借词，也可以接 way、sea 等英语本族词。旧拉丁借词里的写法会变化，现代新构词却多保留清楚的 sub-。',
 forms='sub- 在历史拉丁组合中可同化为 sug-、suf-、sup- 等：suggest 的 sug- 后接 gerere，suffix 的 suf- 后接 figere，support 的 sup- 后接 portare。sus- 等形式同样须按具体词史判断，不能看到相同字母就认作同根。suburban 的 sub- 是靠近城，subacute 是未充分达到某种程度。',
 branches=[['实际位置在下面','subway, submarine, subsea, subsoil, subglacial'],['整体内部的下一层','subset, subgroup, subunit, subcategory, subdomain'],['低于标准或阈值','substandard, subpar, suboptimal, subliminal, subclinical'],['邻近某个地带','suburban, subtropical, subarctic, subalpine'],['合同与管理层级','subcontract, subcontractor, sublet, sublease'],['原本隐藏在表层下面','subconscious, subtext'],['历史同化形式','suggest, suggestion, suffix, support']],
 contrasts='sub- 不一律表示低劣：subgroup 是层级，subhuman 用于人则带贬损；subpar 在一般评价中不好，高尔夫杆数低于标准却可能更好。suburban 在城旁而非地下，suggest 把念头提出来，并不是往下猜。借词 suggestion 在英语中早于 suggest，分别保留历史。',
 practice='读到一个 sub- 词，先问参照物是什么。submarine 参照海面；subcommittee 参照上一级委员会；subzero 参照温标零点；subtext 参照表面说出来的话。这样比统一翻译成“次”更容易看懂。',
 words=[], exclude={})

if __name__ == '__main__':
    manifest = json.loads((BASE / '.cache/batch200/rewrite_vid.json').read_text())
    original = next(r for r in manifest['roots'] if r['id'] == ROOT['id'])
    ROOT['words'] = [w for w in original['family'] if '-' not in w]
    expected = set(ROOT['words']) & set(manifest['owned_words'])
    actual = {e['word'] for e in W}
    assert actual == expected, (expected-actual, actual-expected)
    assert len(W) == len(actual)
    assert all(len(e['examples']) >= 2 and e['ipa'] and len(e['history']) >= 2 for e in W)
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / 'roots_batch200_vid_01.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT / 'words_batch200_vid_01.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('sub:',len(W),'new words;',sum(len(e['examples']) for e in W),'bilingual examples')
